&lt;div id=&quot;d71de5d99b4c42b48ace1879c41b82ca-7170130fcbb85476&quot; data-automation-widget=&quot;richTextArea&quot; data-automation-metadata-id=&quot;56$308486&quot; data-uxi-form-item-child-list-index=&quot;3&quot;&gt;
